// Generated by retro + bun. How prototype links move between screens.
import { router, useNavigation } from 'expo-router';

type Route = { name: string; params?: { screen?: string } };

export function useGo() {
  const navigation = useNavigation();
  return (screen: string) => {
    const state = navigation.getState();
    const routes = (state?.routes ?? []).slice(0, (state?.index ?? 0) + 1) as Route[];
    const at = routes.findLastIndex((r) => r.name === 's/[screen]' && r.params?.screen === screen);
    if (at === routes.length - 1) return; // Already showing it.
    if (at >= 0) router.dismiss(routes.length - 1 - at);
    else router.push({ pathname: '/s/[screen]', params: { screen } });
  };
}
